# Alexandria: spots of daily life, events and stories.
import math

PTOL = ["ptolemy-280", "ptolemaic-200"]
CLASSIC = ["ptolemaic-200", "roman-150ce"]
ROMAN = ["roman-150ce", "late-400"]
LATE = ["late-400"]
OTT = ["ottoman-1600"]

P0 = (31.1966, 29.9003)
KX, KY = 111320.0 * math.cos(math.radians(31.194)), 110950.0


def UV(u, v):
    """(lat, lon) on the ancient street grid, as in geo.py."""
    e = 0.9205 * u - 0.3907 * v
    n = 0.3907 * u + 0.9205 * v
    return (round(P0[0] + n / KY, 5), round(P0[1] + e / KX, 5))


